export class TwitchChat{
 constructor(onChat,onStatus){this.onChat=onChat;this.onStatus=onStatus;this.sockets=new Set();this.seen=new Set();this.stopped=true;this.retry=0;}
 async api(path,options={}){const response=await fetch('https://api.twitch.tv/helix/'+path,{...options,headers:{'Client-Id':this.clientId,Authorization:'Bearer '+this.token,'Content-Type':'application/json'}});if(!response.ok){if(response.status===401)this.disconnect();throw new Error('Twitch '+response.status+': '+(await response.text()).slice(0,180));}return response.json();}
 async connect({token,clientId,channel}){this.disconnect();this.token=token;this.clientId=clientId;this.channel=channel;this.stopped=false;try{await this.validate();const users=await this.api('users?login='+encodeURIComponent(channel));if(!users.data?.length)throw new Error('Channel not found.');this.broadcaster=users.data[0].id;this.open();this.validation=setInterval(()=>this.validate().catch(e=>{this.onStatus(e.message,true);this.disconnect();}),3600000);}catch(e){this.disconnect();throw e;}}
 async validate(){const response=await fetch('https://id.twitch.tv/oauth2/validate',{headers:{Authorization:'OAuth '+this.token}});if(!response.ok)throw new Error('Twitch authorization expired. Connect again.');const data=await response.json();if(data.client_id!==this.clientId||!data.scopes?.includes('user:read:chat'))throw new Error('Authorization does not match this app or lacks chat access.');this.userId=data.user_id;}
 open(url='wss://eventsub.wss.twitch.tv/ws',old=null){if(this.stopped)return;const socket=new WebSocket(url);this.sockets.add(socket);let watchdog;const arm=(seconds)=>{clearTimeout(watchdog);watchdog=setTimeout(()=>socket.close(),(seconds+5)*1000);};arm(20);
 socket.onmessage=async({data})=>{try{if(this.stopped)return;const message=JSON.parse(data),type=message.metadata.message_type;arm(30);if(type==='session_welcome'){arm(message.payload.session.keepalive_timeout_seconds||30);if(old){old.onclose=null;old.close();this.sockets.delete(old);}else await this.api('eventsub/subscriptions',{method:'POST',body:JSON.stringify({type:'channel.chat.message',version:'1',condition:{broadcaster_user_id:this.broadcaster,user_id:this.userId},transport:{method:'websocket',session_id:message.payload.session.id}})});this.retry=0;this.onStatus('Connected to '+this.channel);}
 if(type==='session_reconnect'){const reconnect=message.payload.session.reconnect_url;if(!reconnect?.startsWith('wss://eventsub.wss.twitch.tv/'))throw new Error('Unexpected Twitch reconnect address.');this.open(reconnect,socket);}
 if(type==='notification'){const id=message.metadata.message_id;if(this.seen.has(id))return;this.seen.add(id);if(this.seen.size>2000)this.seen.delete(this.seen.values().next().value);const event=message.payload.event;if(message.payload.subscription.type==='channel.chat.message')this.onChat({user:event.chatter_user_id,name:event.chatter_user_name,text:event.message.text});}
 if(type==='revocation'){this.disconnect();this.onStatus('Chat access revoked. Connect again.',true);}
 }catch(e){this.disconnect();this.onStatus(e.message,true);}};
 socket.onerror=()=>this.onStatus('Twitch connection interrupted',true);
 socket.onclose=()=>{clearTimeout(watchdog);this.sockets.delete(socket);if(!this.stopped&&this.sockets.size===0){this.onStatus('Reconnecting to Twitch…');this.reconnectTimer=setTimeout(()=>this.open(),Math.min(30000,1000*2**this.retry++));}};
 }
 disconnect(){this.stopped=true;clearInterval(this.validation);clearTimeout(this.reconnectTimer);for(const socket of this.sockets){socket.onclose=null;socket.close();}this.sockets.clear();this.token=null;this.seen.clear();}
}
export function authorizationUrl(clientId,redirectUri,state){const params=new URLSearchParams({client_id:clientId,redirect_uri:redirectUri,response_type:'token',scope:'user:read:chat',state});return 'https://id.twitch.tv/oauth2/authorize?'+params;}
